import EfiPy2 as EfiPy

class EfiStatus(int):
    _names = {
        EfiPy.EFI_SUCCESS                   : "EFI_SUCCESS",
        EfiPy.EFI_LOAD_ERROR                : "EFI_LOAD_ERROR",
        EfiPy.EFI_INVALID_PARAMETER         : "EFI_INVALID_PARAMETER",
        EfiPy.EFI_UNSUPPORTED               : "EFI_UNSUPPORTED",
        EfiPy.EFI_BAD_BUFFER_SIZE           : "EFI_BAD_BUFFER_SIZE",
        EfiPy.EFI_BUFFER_TOO_SMALL          : "EFI_BUFFER_TOO_SMALL",
        EfiPy.EFI_NOT_READY                 : "EFI_NOT_READY",
        EfiPy.EFI_DEVICE_ERROR              : "EFI_DEVICE_ERROR",
        EfiPy.EFI_WRITE_PROTECTED           : "EFI_WRITE_PROTECTED",
        EfiPy.EFI_OUT_OF_RESOURCES          : "EFI_OUT_OF_RESOURCES",
        EfiPy.EFI_VOLUME_CORRUPTED          : "EFI_VOLUME_CORRUPTED",
        EfiPy.EFI_VOLUME_FULL               : "EFI_VOLUME_FULL",
        EfiPy.EFI_NO_MEDIA                  : "EFI_NO_MEDIA",
        EfiPy.EFI_MEDIA_CHANGED             : "EFI_MEDIA_CHANGED",
        EfiPy.EFI_NOT_FOUND                 : "EFI_NOT_FOUND",
        EfiPy.EFI_ACCESS_DENIED             : "EFI_ACCESS_DENIED",
        EfiPy.EFI_NO_RESPONSE               : "EFI_NO_RESPONSE",
        EfiPy.EFI_NO_MAPPING                : "EFI_NO_MAPPING",
        EfiPy.EFI_TIMEOUT                   : "EFI_TIMEOUT",
        EfiPy.EFI_NOT_STARTED               : "EFI_NOT_STARTED",
        EfiPy.EFI_ALREADY_STARTED           : "EFI_ALREADY_STARTED",
        EfiPy.EFI_ABORTED                   : "EFI_ABORTED",
        EfiPy.EFI_ICMP_ERROR                : "EFI_ICMP_ERROR",
        EfiPy.EFI_TFTP_ERROR                : "EFI_TFTP_ERROR",
        EfiPy.EFI_PROTOCOL_ERROR            : "EFI_PROTOCOL_ERROR",
        EfiPy.EFI_INCOMPATIBLE_VERSION      : "EFI_INCOMPATIBLE_VERSION",
        EfiPy.EFI_SECURITY_VIOLATION        : "EFI_SECURITY_VIOLATION",
        EfiPy.EFI_CRC_ERROR                 : "EFI_CRC_ERROR",
        EfiPy.EFI_END_OF_MEDIA              : "EFI_END_OF_MEDIA",
        EfiPy.EFI_END_OF_FILE               : "EFI_END_OF_FILE",
        EfiPy.EFI_INVALID_LANGUAGE          : "EFI_INVALID_LANGUAGE",
        EfiPy.EFI_COMPROMISED_DATA          : "EFI_COMPROMISED_DATA",
        EfiPy.EFI_IP_ADDRESS_CONFLICT       : "EFI_IP_ADDRESS_CONFLICT",
        EfiPy.EFI_HTTP_ERROR                : "EFI_HTTP_ERROR",
        EfiPy.EFI_WARN_UNKNOWN_GLYPH        : "EFI_WARN_UNKNOWN_GLYPH",
        EfiPy.EFI_WARN_DELETE_FAILURE       : "EFI_WARN_DELETE_FAILURE",
        EfiPy.EFI_WARN_WRITE_FAILURE        : "EFI_WARN_WRITE_FAILURE",
        EfiPy.EFI_WARN_BUFFER_TOO_SMALL     : "EFI_WARN_BUFFER_TOO_SMALL",
        EfiPy.EFI_WARN_STALE_DATA           : "EFI_WARN_STALE_DATA",
        EfiPy.EFI_WARN_FILE_SYSTEM          : "EFI_WARN_FILE_SYSTEM",
        EfiPy.EFI_WARN_RESET_REQUIRED       : "EFI_WARN_RESET_REQUIRED",
        EfiPy.EFI_NETWORK_UNREACHABLE       : "EFI_NETWORK_UNREACHABLE",
        EfiPy.EFI_HOST_UNREACHABLE          : "EFI_HOST_UNREACHABLE",
        EfiPy.EFI_PROTOCOL_UNREACHABLE      : "EFI_PROTOCOL_UNREACHABLE",
        EfiPy.EFI_PORT_UNREACHABLE          : "EFI_PORT_UNREACHABLE",
        EfiPy.EFI_CONNECTION_FIN            : "EFI_CONNECTION_FIN",
        EfiPy.EFI_CONNECTION_RESET          : "EFI_CONNECTION_RESET",
        EfiPy.EFI_CONNECTION_REFUSED        : "EFI_CONNECTION_REFUSED",
    }

    def __str__(self):
        return self._names.get(
            int(self),
            "EFI_STATUS(0x{:X})".format(int(self))
        )